import{_ as s,l as n,o as e,c as l,v as o,p as i,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"聚簇索引与回表","description":"","frontmatter":{"title":"聚簇索引与回表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clustered-secondary-lookup.md","filePath":"cs/clustered-secondary-lookup.md","lastUpdated":1789023840000}'),h={name:"cs/clustered-secondary-lookup.md"};function u(E,a,_,B,m,A){const t=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="聚簇索引与回表" tabindex="-1">聚簇索引与回表 <a class="header-anchor" href="#聚簇索引与回表" aria-label="Permalink to &quot;聚簇索引与回表&quot;">​</a></h1><div class="epigraph"><p>二级索引命中后要回主存储取行：聚簇上回主键，堆上回 TID。覆盖则免回表；回表随机 I/O 是二级路径的主税。</p><footer>—— 据 Ramakrishnan and Gehrke；覆盖索引课的引擎落地</footer></div><p><a href="/cs/pg-vacuum">上一课</a>回收堆上死版本。本课不扫可见性映射。缺口是点查与范围走二级索引之后：<strong>回表</strong>（bookmark lookup / heap fetch）。主干 <a href="/cs/covering-index">覆盖索引</a> 已给免回表条件；对照序列要把 InnoDB 主键回表与 Postgres TID 回表钉在同一机制图里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二级叶子存 (二级键, 主键或 TID)。过滤若只需二级键，仍可能为投影回表。范围扫描二级有序，回表按主键或 TID 随机——顺序二级 + 随机主存储，计划可能不如按主键聚簇扫。缺口是优化器何时选「二级+回表」vs「全聚簇/堆扫」vs「覆盖」。</p><p>InnoDB：回表是再走主键 B+（通常缓存热）。Postgres：TID 直接堆页，可能更短，但堆无序。位图扫描：先收集 TID 排序再堆取，把随机变顺序，这是迟物化在堆上的实例。</p><p><span class="marginnote">回表次数 ≈ 幸存行数（非覆盖时）。选择率估错会低估随机 I/O，计划回归常见形态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>INCLUDE/covering 把投影列塞进二级叶子。聚簇设计：把最常范围查询的键当主键，让该路径免二级。哈希二级只服务等值，回表同样发生。</p><p>并行：回表 gather 要批量化，否则随机 I/O 打满队列。缓冲：回表页若一次性，2Q 应逐出。</p>',10)),(e(),i(c,null,{default:r(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEC%5B%22%E4%BA%8C%E7%BA%A7%E5%8F%B6%22%5D%20--%3E%20COV%5B%22%E5%88%97%E5%B7%B2%E8%A6%86%E7%9B%96%3F%22%5D%0A%20%20COV%20--%3E%7C%22%E6%98%AF%22%7C%20OUT%5B%22%E5%8F%AA%E6%89%AB%E4%BA%8C%E7%BA%A7%22%5D%0A%20%20COV%20--%3E%7C%22%E5%90%A6%22%7C%20LK%5B%22%E5%9B%9E%E4%B8%BB%E9%94%AE%E6%88%96%20TID%22%5D%0A%20%20LK%20--%3E%20ROW%5B%22%E4%B8%BB%E5%AD%98%E5%82%A8%E8%A1%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MVCC：回表看到的行要符合快照；Postgres 可能发现 TID 上版本不可见再跟 HOT 链。InnoDB 回聚簇已是当前行，旧版走 undo。锁：先闩页再行锁，顺序固定。</p><p>索引组织下一课把「没有独立堆」说绝：整表就是一棵主键树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 IOT 溢出与二级非键列写完。也不讲学习索引回表。宽表回表更贵，垂直拆分或列存是另一布局。</p><p>后课默认：非覆盖二级必回表；估计幸存行。索引组织表：主键树即表，二级仍回主键。</p><p>回表是物理，不是 JOIN 的另一种写法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二级路径的税是回表随机 I/O；覆盖与位图排序减轻。</li><li>InnoDB 回主键，Postgres 回 TID。</li><li>索引组织表下一课：表即主键 B+。</li><li>出处：Ramakrishnan and Gehrke；覆盖索引对照。</li></ul>',9))])}const I=s(h,[["render",u]]);export{D as __pageData,I as default};
